<?php defined('ABSPATH')||exit; get_header(); ?>
<main class="tutor-container tutor-py-48"><div class="tutor-card"><div class="tutor-card-body">
<h1><?php esc_html_e('Training invitation','tutor');?></h1>
<?php if(!$batch): ?><div class="tutor-alert tutor-danger"><?php esc_html_e('This invitation is invalid.','tutor');?></div>
<?php else: ?><h2><?php echo esc_html(get_the_title($batch->course_id));?></h2><p><?php printf(esc_html__('Invitation expires: %s','tutor'),esc_html(get_date_from_gmt($batch->expires_at,get_option('date_format').' '.get_option('time_format'))));?></p>
<?php if(is_wp_error($result)): ?><div class="tutor-alert tutor-danger"><?php echo esc_html($result->get_error_message());?></div><?php elseif(is_array($result)): ?><div class="tutor-alert tutor-success"><?php echo esc_html('completed'===$result['status']?__('Enrollment completed.','tutor'):__('You already have access to this course.','tutor'));?></div><p><a class="tutor-btn tutor-btn-primary" href="<?php echo esc_url(get_permalink($batch->course_id));?>"><?php esc_html_e('View course','tutor');?></a></p><?php elseif(!is_user_logged_in()): ?><p><a class="tutor-btn tutor-btn-primary" href="<?php echo esc_url(wp_login_url(home_url('/training/redeem/'.$token.'/')));?>"><?php esc_html_e('Log in or register to continue','tutor');?></a></p><?php else: ?><form method="post"><?php wp_nonce_field('kte_redeem_'.$batch->id);?><button class="tutor-btn tutor-btn-primary" type="submit"><?php esc_html_e('Redeem enrollment','tutor');?></button></form><?php endif; endif; ?>
</div></div></main><?php get_footer(); ?>
